import{_ as o,o as a,c as s,a as e}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-022","description":"","frontmatter":{"date":"2020-08-11T20:10:10","title":"写作课作业-022","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/022.md","filePath":"posts/homework/022.md"}'),l={name:"posts/homework/022.md"};function r(n,t,p,c,i,u){return a(),s("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"举生活中一两个例子来说明理解“易得性偏差”的重要性，怎么使其为我所用？")],-1),e("p",null,"初中时，同学间会玩这样一个游戏，一个同学说，三点水一个来，叫“lai”，三点水一个去，叫什么？另一个同学答“qu”，边上玩过这个游戏的人就会起哄的笑起来。",-1),e("p",null,"这是个易得性偏差的例子。那什么是易得性偏差呢？人们由于受记忆力或知识的局限，在形成自己的判断过程中，往往会赋予那些易见的、容易记起的信息以过大的权重，而对大量的其他必须考虑的信息“视而不见”，仅仅基于易见的、容易记起的信息作判断。《思考，快与慢》中说，系统2具备推理能力，它很谨慎，但它是懒惰的，往往会遵循最省力法则，不经检验就认可系统1，而系统1常常犯各种错误。易得性偏差往往是系统2不工作引起的。",-1),e("p",null,"广告是易得性偏差的重灾区，通过不断重复的广告语，我们很容易就为之买单了。而实际上，常年靠广告来营销的商品，特别是那种很贵的广告，很可能是在收我们的智商税。而利用重复获得易得性，也可以为我们所有，比如每天读书，无论多少，不仅影响自己，还能影响下一代。",-1),e("p",null,"而在一些事情上，我们需要打破易得性的链路，使系统2启动起来。我爱人平时比较爱吃零食，原来零食放客厅。后来她决定减肥，我建议她把零食收起来。当她想吃的时候，不能马上拿到，一番思想斗争下来可能就不想吃了。通过“管住嘴，迈开腿”她减了10多斤。",-1)])])}const _=o(l,[["render",r]]);export{m as __pageData,_ as default};
